const W = 1024;
const H = 1368;

const CREAM = "#f6f1e7";
const INK = "#211f1b";
const MUTED = "#6f6a60";
const ACCENT = "#c25a3e";
const LINE = "#dcd2c1";

const SANS = '"DM Sans", Arial, sans-serif';
const SERIF = '"Fraunces", Georgia, serif';

function makeCanvas() {
  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  return canvas;
}

function setFont(ctx, size, family = SANS, weight = 400, italic = false) {
  ctx.font = `${italic ? "italic " : ""}${weight} ${size}px ${family}`;
}

function tracking(ctx, value) {
  if ("letterSpacing" in ctx) {
    ctx.letterSpacing = value;
  }
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight, maxLines = Infinity) {
  const words = text.split(/\s+/);
  let line = "";
  let lines = 0;

  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;

    if (ctx.measureText(candidate).width > maxWidth && line) {
      ctx.fillText(line, x, y);
      y += lineHeight;
      lines += 1;

      if (lines >= maxLines) {
        return y;
      }

      line = word;
    } else {
      line = candidate;
    }
  }

  if (line) {
    ctx.fillText(line, x, y);
    y += lineHeight;
  }

  return y;
}

function drawCover(profile) {
  const canvas = makeCanvas();
  const ctx = canvas.getContext("2d");

  ctx.fillStyle = INK;
  ctx.fillRect(0, 0, W, H);

  ctx.strokeStyle = "rgba(246,241,231,0.26)";
  ctx.lineWidth = 2;
  ctx.strokeRect(46, 46, W - 92, H - 92);

  ctx.strokeStyle = ACCENT;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(46, 46);
  ctx.lineTo(212, 46);
  ctx.stroke();

  ctx.save();
  ctx.strokeStyle = "rgba(194,90,62,0.3)";
  ctx.lineWidth = 2;
  for (let index = 0; index < 5; index += 1) {
    ctx.beginPath();
    ctx.arc(W - 150, 470, 96 + index * 48, -0.95, 1.95);
    ctx.stroke();
  }
  ctx.restore();

  ctx.fillStyle = "rgba(246,241,231,0.68)";
  setFont(ctx, 25, SANS, 500);
  tracking(ctx, "4px");
  ctx.fillText("PERSONAL PORTFOLIO  /  2026", 96, 126);
  tracking(ctx, "0px");

  ctx.fillStyle = CREAM;
  setFont(ctx, 132, SERIF, 500);
  const [first, ...rest] = profile.name.split(" ");
  ctx.fillText(first, 92, 372);
  ctx.fillText(rest.join(" "), 92, 512);

  ctx.fillStyle = ACCENT;
  setFont(ctx, 37, SANS, 500);
  tracking(ctx, "3px");
  ctx.fillText(profile.role.toUpperCase(), 98, 606);
  tracking(ctx, "0px");

  ctx.strokeStyle = "rgba(246,241,231,0.28)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(96, 662);
  ctx.lineTo(W - 96, 662);
  ctx.stroke();

  ctx.fillStyle = "rgba(246,241,231,0.62)";
  setFont(ctx, 28, SANS, 400);
  ctx.fillText(profile.location, 96, 722);

  ctx.fillStyle = ACCENT;
  setFont(ctx, 30, SANS, 500);
  ctx.fillText("Balik halaman untuk mulai  →", 96, H - 118);

  return canvas;
}

function drawFooter(ctx, profile, pageNumber, total) {
  ctx.strokeStyle = LINE;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(110, H - 120);
  ctx.lineTo(W - 110, H - 120);
  ctx.stroke();

  ctx.fillStyle = MUTED;
  setFont(ctx, 21, SANS, 500);
  tracking(ctx, "2px");
  ctx.fillText(profile.name.toUpperCase(), 110, H - 74);

  const number = `${String(pageNumber).padStart(2, "0")} / ${String(total).padStart(2, "0")}`;
  ctx.fillText(number, W - 110 - ctx.measureText(number).width, H - 74);
  tracking(ctx, "0px");
}

function drawAbout(ctx, page) {
  ctx.fillStyle = "#514c43";
  setFont(ctx, 31, SANS, 400);

  let y = 430;
  for (const paragraph of page.body) {
    y = wrapText(ctx, paragraph, 112, y, 800, 48) + 30;
  }

  const boxY = y + 12;
  ctx.fillStyle = "rgba(194,90,62,0.09)";
  ctx.fillRect(110, boxY, 800, 126);
  ctx.fillStyle = ACCENT;
  ctx.fillRect(110, boxY, 6, 126);

  ctx.fillStyle = INK;
  setFont(ctx, 27, SANS, 500);
  wrapText(ctx, page.note, 146, boxY + 52, 730, 42, 2);
}

function drawSkills(ctx, page) {
  let y = 444;

  page.items.forEach((item, index) => {
    ctx.fillStyle = ACCENT;
    setFont(ctx, 22, SANS, 600);
    ctx.fillText(String(index + 1).padStart(2, "0"), 112, y);

    ctx.fillStyle = INK;
    setFont(ctx, 42, SERIF, 500);
    ctx.fillText(item.name, 184, y);

    ctx.fillStyle = MUTED;
    setFont(ctx, 25, SANS, 400);
    ctx.fillText(item.detail, 184, y + 40);

    ctx.fillStyle = "#e3d9c9";
    ctx.fillRect(184, y + 64, 628, 4);
    ctx.fillStyle = ACCENT;
    ctx.fillRect(184, y + 64, 628 * item.level, 4);

    y += 164;
  });
}

function drawWork(ctx, page) {
  let y = 436;

  page.items.forEach((item, index) => {
    ctx.fillStyle = ACCENT;
    setFont(ctx, 56, SERIF, 500);
    ctx.fillText(String(index + 1).padStart(2, "0"), 112, y);

    ctx.fillStyle = INK;
    setFont(ctx, 46, SERIF, 500);
    ctx.fillText(item.title, 230, y);

    ctx.fillStyle = MUTED;
    setFont(ctx, 25, SANS, 400);
    ctx.fillText(`${item.role}  ·  ${item.year}`, 230, y + 40);

    ctx.strokeStyle = LINE;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(112, y + 72);
    ctx.lineTo(W - 112, y + 72);
    ctx.stroke();

    y += 156;
  });
}

function drawContact(ctx, page) {
  ctx.fillStyle = "#514c43";
  setFont(ctx, 31, SANS, 400);
  let y = wrapText(ctx, page.body, 112, 430, 800, 48) + 66;

  ctx.fillStyle = ACCENT;
  setFont(ctx, 54, SERIF, 500);
  ctx.fillText(page.email, 112, y);

  y += 92;
  ctx.fillStyle = INK;
  setFont(ctx, 27, SANS, 400);
  for (const line of page.lines) {
    ctx.fillText(`—  ${line}`, 112, y);
    y += 48;
  }
}

function drawContent(profile, page, pageNumber, total) {
  const canvas = makeCanvas();
  const ctx = canvas.getContext("2d");

  ctx.fillStyle = CREAM;
  ctx.fillRect(0, 0, W, H);

  ctx.fillStyle = "#ebe2d3";
  ctx.fillRect(58, 0, 10, H);

  ctx.fillStyle = ACCENT;
  setFont(ctx, 24, SANS, 600);
  tracking(ctx, "4px");
  ctx.fillText(page.label.toUpperCase(), 112, 118);
  tracking(ctx, "0px");

  ctx.fillStyle = INK;
  setFont(ctx, 78, SERIF, 500);
  let headingY = 238;
  for (const line of page.heading.split("\n")) {
    ctx.fillText(line, 110, headingY);
    headingY += 94;
  }

  if (page.kind === "about") {
    drawAbout(ctx, page);
  } else if (page.kind === "skills") {
    drawSkills(ctx, page);
  } else if (page.kind === "work") {
    drawWork(ctx, page);
  } else if (page.kind === "contact") {
    drawContact(ctx, page);
  }

  drawFooter(ctx, profile, pageNumber, total);

  return canvas;
}

function drawBack(profile, index) {
  const canvas = makeCanvas();
  const ctx = canvas.getContext("2d");

  ctx.fillStyle = "#efe7d9";
  ctx.fillRect(0, 0, W, H);

  ctx.strokeStyle = "#ded3c1";
  ctx.lineWidth = 2;
  ctx.strokeRect(46, 46, W - 92, H - 92);

  ctx.fillStyle = "rgba(33,31,27,0.09)";
  setFont(ctx, 168, SERIF, 500);
  ctx.textAlign = "center";
  ctx.fillText(profile.initials, W / 2, H / 2 + 40);

  ctx.fillStyle = "#a19788";
  setFont(ctx, 22, SANS, 500);
  tracking(ctx, "5px");
  ctx.fillText("PORTFOLIO", W / 2, H / 2 + 110);
  tracking(ctx, "0px");
  ctx.textAlign = "left";

  ctx.fillStyle = "#a19788";
  setFont(ctx, 22, SANS, 500);
  ctx.fillText(String(index).padStart(2, "0"), 112, H - 88);

  return canvas;
}

function toTexture(canvas, anisotropy) {
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = anisotropy || 1;
  return texture;
}

export function createPageTextures({ profile, pages }, anisotropy) {
  return pages.map((page, index) => ({
    front:
      page.kind === "cover"
        ? toTexture(drawCover(profile), anisotropy)
        : toTexture(drawContent(profile, page, index, pages.length), anisotropy),
    back: toTexture(drawBack(profile, index), anisotropy),
  }));
}
