import { createPageTextures } from "./pages.js";

const PAGE_W = 2.5;
const PAGE_H = 3.34;
const PAGE_T = 0.028;

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function easeInOutCubic(value) {
  return value < 0.5 ? 4 * value ** 3 : 1 - (-2 * value + 2) ** 3 / 2;
}

export function createBook(container, data, options = {}) {
  const reducedMotion = options.reducedMotion ?? false;
  const onChange = options.onChange ?? (() => {});

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(36, 1, 0.1, 100);
  camera.position.set(0, 0.2, 9);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.12;
  container.appendChild(renderer.domElement);

  scene.add(new THREE.AmbientLight(0xffffff, 2.4));

  const keyLight = new THREE.DirectionalLight(0xfff3df, 2.8);
  keyLight.position.set(-3, 5, 7);
  scene.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0xd8e2ff, 0.9);
  fillLight.position.set(4, -2, 5);
  scene.add(fillLight);

  const bookGroup = new THREE.Group();
  scene.add(bookGroup);

  const maxAnisotropy = renderer.capabilities.getMaxAnisotropy();
  const textures = createPageTextures(data, maxAnisotropy);
  const edgeMaterial = new THREE.MeshStandardMaterial({
    color: 0xe7ddcd,
    roughness: 0.95,
  });
  const leaves = [];

  textures.forEach(({ front, back }, index) => {
    const frontMaterial = new THREE.MeshStandardMaterial({
      map: front,
      roughness: 0.86,
    });
    const backMaterial = new THREE.MeshStandardMaterial({
      map: back,
      roughness: 0.86,
    });

    // BoxGeometry faces: +x, -x, +y, -y, +z (front), -z (back).
    const materials = [
      edgeMaterial,
      edgeMaterial,
      edgeMaterial,
      edgeMaterial,
      frontMaterial,
      backMaterial,
    ];
    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(PAGE_W, PAGE_H, PAGE_T),
      materials,
    );
    mesh.position.x = PAGE_W / 2;

    const pivot = new THREE.Group();
    pivot.add(mesh);
    pivot.position.z = -index * PAGE_T;
    bookGroup.add(pivot);

    leaves.push({ pivot, index });
  });

  let current = 0;
  let animation = null;
  const pointer = { x: 0, y: 0, down: false, startX: 0 };

  function animateTo(target, duration = 880) {
    const next = clamp(target, 0, leaves.length - 1);

    animation = {
      start: performance.now(),
      duration: reducedMotion ? 0 : duration,
      items: leaves.map((leaf) => {
        const isFlipped = leaf.index < next;
        return {
          pivot: leaf.pivot,
          fromRotation: leaf.pivot.rotation.y,
          toRotation: isFlipped ? -Math.PI : 0,
          fromZ: leaf.pivot.position.z,
          toZ: isFlipped ? leaf.index * PAGE_T + 0.001 : -leaf.index * PAGE_T,
          delay: Math.abs(leaf.index - current) * 55,
        };
      }),
    };

    if (current !== next) {
      current = next;
      onChange(current);
    }
  }

  function next() {
    animateTo(current + 1);
  }

  function prev() {
    animateTo(current - 1);
  }

  function updateAnimation(now) {
    if (!animation) {
      return;
    }

    let finished = true;

    for (const item of animation.items) {
      const elapsed = now - animation.start - item.delay;
      const progress =
        animation.duration === 0 ? 1 : clamp(elapsed / animation.duration, 0, 1);
      const eased = easeInOutCubic(progress);

      item.pivot.rotation.y =
        item.fromRotation + (item.toRotation - item.fromRotation) * eased;
      item.pivot.position.z =
        item.fromZ + (item.toZ - item.fromZ) * eased;

      if (progress < 1) {
        finished = false;
      }
    }

    if (finished) {
      animation = null;
    }
  }

  const canvas = renderer.domElement;
  canvas.setAttribute("aria-hidden", "true");

  canvas.addEventListener("pointerdown", (event) => {
    pointer.down = true;
    pointer.startX = event.clientX;
    canvas.setPointerCapture(event.pointerId);
  });

  canvas.addEventListener("pointermove", (event) => {
    const rect = canvas.getBoundingClientRect();
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = ((event.clientY - rect.top) / rect.height) * 2 - 1;
  });

  canvas.addEventListener("pointerup", (event) => {
    pointer.down = false;
    const delta = event.clientX - pointer.startX;

    if (Math.abs(delta) > 55) {
      if (delta < 0) {
        next();
      } else {
        prev();
      }
      return;
    }

    const rect = canvas.getBoundingClientRect();
    const clickedRight = event.clientX - rect.left > rect.width / 2;
    if (clickedRight) {
      next();
    } else {
      prev();
    }
  });

  canvas.addEventListener("pointerleave", () => {
    pointer.x = 0;
    pointer.y = 0;
  });

  function resize() {
    const width = container.clientWidth;
    const height = container.clientHeight;
    if (!width || !height) {
      return;
    }

    renderer.setSize(width, height, false);
    camera.aspect = width / height;

    const halfFov = THREE.MathUtils.degToRad(camera.fov / 2);
    const distanceForWidth =
      (PAGE_W * 2 + 0.7) / (2 * Math.tan(halfFov) * camera.aspect);
    const distanceForHeight = (PAGE_H + 1) / (2 * Math.tan(halfFov));

    camera.position.z = Math.max(distanceForWidth, distanceForHeight, 7.4);
    camera.updateProjectionMatrix();
  }

  const observer = new ResizeObserver(resize);
  observer.observe(container);
  resize();

  const smoothed = { x: 0, y: 0 };
  let frameId = 0;

  function tick(now) {
    const seconds = now * 0.001;

    updateAnimation(now);

    const targetX = current === 0 ? -PAGE_W / 2 : 0;
    bookGroup.position.x += (targetX - bookGroup.position.x) * 0.09;

    if (!reducedMotion) {
      smoothed.x += (pointer.x - smoothed.x) * 0.05;
      smoothed.y += (pointer.y - smoothed.y) * 0.05;
      bookGroup.rotation.y = smoothed.x * 0.18 + Math.sin(seconds * 0.5) * 0.025;
      bookGroup.rotation.x = -smoothed.y * 0.1 + Math.sin(seconds * 0.72) * 0.018;
      bookGroup.position.y = Math.sin(seconds * 0.9) * 0.045;
    }

    renderer.render(scene, camera);
    frameId = requestAnimationFrame(tick);
  }

  frameId = requestAnimationFrame(tick);

  function dispose() {
    cancelAnimationFrame(frameId);
    observer.disconnect();
    renderer.dispose();
  }

  return { next, prev, goTo: animateTo, getPage: () => current, dispose };
}
