  ctx.fillText(String(index).padStart(2, "0"), 112, H - 88);

  return canvas;
}","newString":"function drawBack(profile, index, chapters) {
  const canvas = makeCanvas();
  const ctx = canvas.getContext("2d");

  ctx.fillStyle = "#efe7d9";
  ctx.fillRect(0, 0, W, H);

  ctx.strokeStyle = "#ded3c1";
  ctx.lineWidth = 2;
  ctx.strokeRect(46, 46, W - 92, H - 92);

  if (index === 0) {
    ctx.fillStyle = ACCENT;
    setFont(ctx, 25, SANS, 600);
    tracking(ctx, "4px");
    ctx.fillText("DAFTAR ISI", 112, 160);
    tracking(ctx, "0px");

    let y = 300;
    chapters.forEach((chapter, chapterIndex) => {
      ctx.fillStyle = ACCENT;
      setFont(ctx, 30, SANS, 600);
      ctx.fillText(String(chapterIndex + 1).padStart(2, "0"), 112, y);

      ctx.fillStyle = INK;
      setFont(ctx, 52, SERIF, 500);
      ctx.fillText(chapter, 190, y);

      ctx.strokeStyle = "#ddd1bf";
      ctx.lineWidth = 1;
      ctx.beginPath();
