{"path":"C:\Users\Quincy\Projects\portfolio-book\src\main.js","content":"import "./style.css";
import { profile, pages, projects } from "./data.js";
import { createBook } from "./book.js";

const totalPages = pages.length;

document.querySelector("#year").textContent = new Date().getFullYear();
document.querySelector("#contactMail").href = `mailto:${profile.email}`;

const workGrid = document.querySelector("#workGrid");
workGrid.innerHTML = projects
  .map(
    (project) => `
      <article class="project-card">
        <div class="project-art ${project.art}" aria-hidden="true">
          <span>${project.number}</span>
        </div>
        <div class="project-body">
          <p class="project-meta">
            <span>${project.role}</span>
            <span>${project.year}</span>
          </p>
          <h3>${project.title}</h3>
          <p>${project.description}</p>
          <ul class="tags">${project.tags.map((tag) => `<li>${tag}</li>`).join("")}</ul>
        </div>
      </article>
    `,
  )
  .join("");

const pageLabel = document.querySelector("#pageLabel");
const pageDots = document.querySelector("#pageDots");
const prevButton = document.querySelector("#prevPage");
const nextButton = document.querySelector("#nextPage");

const dots = pages.map((_, index) => {
  const button = document.createElement("button");
  button.type = "button";
  button.setAttribute("aria-label", `Buka halaman ${index + 1}`);
  button.addEventListener("click", () => book.goTo(index));
  pageDots.appendChild(button);
  return button;
});

function formatPage(index) {
  return `${String(index + 1).padStart(2, "0")} / ${String(totalPages).padStart(2, "0")}`;
}

function handleChange(page) {
  pageLabel.textContent = formatPage(page);
  prevButton.disabled = page === 0;
  nextButton.disabled = page === totalPages - 1;
  dots.forEach((dot, index) => {
    dot.setAttribute("aria-current", String(index === page));
  });
}

const book = createBook(
  document.querySelector("#bookCanvas"),
  { profile, pages },
  {
    reducedMotion: window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    onChange: handleChange,
  },
);

prevButton.addEventListener("click", () => book.prev());
nextButton.addEventListener("click", () => book.next());
document.querySelector("#openBook").addEventListener("click", () => book.goTo(1));

window.addEventListener("keydown", (event) => {
  const target = event.target;
  if (target instanceof HTMLElement && /INPUT|TEXTAREA|SELECT/.test(target.tagName)) {
    return;
  }

  if (event.key === "ArrowRight") {
    book.next();
  } else if (event.key === "ArrowLeft") {
    book.prev();
  }
});

handleChange(0);
"}

